export function ProgressIndicator({
  style = "{{style}}",
  value = {{value}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      {style === "bar" && (
        <div role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100} style={{ height: 10, background: "#24143014", borderRadius: 999, overflow: "hidden" }}>
          <span style={{ display: "block", height: "100%", width: `${value}%`, background: accent, borderRadius: 999 }} />
        </div>
      )}
      {style === "circular" && (
        <svg viewBox="0 0 60 60" width="60" height="60" role="progressbar" aria-valuenow={value}>
          <circle cx="30" cy="30" r="26" fill="none" stroke="#24143022" strokeWidth="6" />
          <circle cx="30" cy="30" r="26" fill="none" stroke={accent} strokeWidth="6" strokeDasharray="163.4" style={{ strokeDashoffset: `calc(163.4px - (163.4px * ${value} / 100))`, transform: "rotate(-90deg)", transformOrigin: "50% 50%" }} />
        </svg>
      )}
      {style === "steps" && (
        <div style={{ display: "flex", gap: 6, justifyContent: "center" }}>
          <span style={{ width: 40, height: 8, borderRadius: 4, background: accent }} />
          <span style={{ width: 40, height: 8, borderRadius: 4, background: accent }} />
          <span style={{ width: 40, height: 8, borderRadius: 4, background: "#24143022" }} />
        </div>
      )}
      <p style={{ margin: "10px 0 0" }}>{value}% complete</p>
    </div>
  );
}
